# aplicar-boton-volver-y-fix-firmado.ps1
#
# Aplica, en tu clon local de fpt-contratos:
#   1. Boton 'Volver' (regresa a donde entraste) en el expediente de un
#      contrato, ademas del 'Volver al listado' que ya existia.
#   2. Un script de correccion de datos (una sola vez) que marca como
#      'Firmado' los Franchise Agreement que se cargaron en bloque y que
#      hoy se ven como 'Pendiente de firma' por error de categoria.
#
# Como correrlo:
#   1. Abre PowerShell en la carpeta raiz de tu clon de fpt-contratos.
#   2. .\aplicar-boton-volver-y-fix-firmado.ps1
#
# Despues de correrlo, falta UN paso en el servidor (igual que la vez
# pasada, con DATABASE_URL de produccion -- el mismo .env que usaste para
# migrate:franquicia-alertas, o repite el proceso de copiarlo de Render):
#   cd backend
#   npm run fix:franquicias-firmado
#
# El deploy del codigo (boton Volver) se dispara solo con el push, si
# tienes auto-deploy activado en Render (la vez pasada si se disparo solo).

$ErrorActionPreference = "Stop"

function Write-FileFromBase64($relPath, $b64) {
    $full = Join-Path (Get-Location) $relPath
    $dir = Split-Path $full -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "Escrito: $relPath"
}

if (-not (Test-Path ".git")) {
    Write-Host "No encuentro una carpeta .git aqui. Corre este script desde la raiz de tu clon de fpt-contratos." -ForegroundColor Red
    exit 1
}

